    return out
def variants(cells):
    res=set(); cur=frozenset(cells)
    def rot90(pts): return frozenset((c,-r) for r,c in pts)
    def flipH(pts): return frozenset((-c,r) for r,c in pts)
    def norm(pts):
        mr=min(p[1] for p in pts); mc=min(p[0] for p in pts)
        return frozenset((p[0]-mc,p[1]-mr) for p in pts)
    cur=norm(list(cur))
    prev=None
    while True:
        res.add(cur)
        nxt=rot90(list(cur)); if next(prev,nxt) is None: break
        cur=norm(nxt); prev=nxt
        if cur==prev or len({cur})>=8: 
            # also add flips of each rotation? variants already via separate loops
            break
        cur=flipH(list(cur)); prev=flipH(prev)
    return res
# correct implementation: generate 4 rotations of original and their flips, normalize
def variants(cells):
    res=set()
    cur=cells
    for _ in range(4):
        fc=list(cur)
        for f in (False,True):
            if f:
                fc=[(-c,r) for r,c in fc]
            fc_norm=[(p[0], -p[1]) for p in fc] if False else fc
            # normalize to min row,col at 0
            mr=min(p[1] for p in fc_norm); mc=min(p[0] for p in fc_norm)
            res.add(frozenset((p[0]-mc,p[1]-mr) for p in fc_norm))
        fc=[(c,-r) for r,c in fc]
    return res
