# For each demo: compare added-group shapes to the template shape and its dihedral variants.
for i in range(1,9):
    gi,go=G['Demo pair %d input'%i],G['Demo pair %d output'%i]
    H,W=len(gi),len(gi[0])
    cin=comps(gi)
