                nb=(r+dr,c+dc)
                if nb in diffs and nb not in seen and nb not in comp:
                    st.append(nb); comp.add(nb)
        seen|=comp; grps.append((col_,sorted(comp)))
    # sym variants of a pattern P as hashable tuples-of-tuples frozensets
    def syms(P):
        R=set(frozenset({(a,b) for a,b in P})); cur=frozenset(P)
        out=[cur]
