def comps(g,bg=None):
    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]; res=[]
    if bg is None: bg=Counter(x for row in g for x in row).most_common(1)[0][0]
    for r in range(h):
        for c_ in range(w):
            if g[r][c_]!=bg and not seen[r][c_]:
                col=g[r][c_]; q=deque([(r,c_)]); cells=[]; seen[r][c_]=True
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+dr,b+dc
                        if 0<=x<h and 0<=y<w and not seen[x][y] and g[x][y]==col:
                            seen[x][y]=True;q.append((x,y))
                res.append({'cells':cells,'color':col})
    return res
